import type {AddressInfo} from 'node:net';
import {WebSocket} from 'ws';
import type {Express} from 'express';
import {createServer} from './createServer.js';
import {HAL_WS_SUBPROTOCOL} from './ws/subprotocol.js';
import {answeringOrchestrator, stopEngines} from './wsTestSupport.js';
import {InMemorySessionStore} from '../infrastructure/stores/inMemorySessionStore.js';

interface Frame {
  type: string;
  code?: string;
  sessions?: unknown[];
}

const askAfterConnect = async (url: string, outbound: unknown): Promise<Frame[]> => {
  const client = new WebSocket(url, [HAL_WS_SUBPROTOCOL]);
  const frames: Frame[] = [];
  await new Promise<void>(resolve => {
    client.on('message', raw => {
      const frame = JSON.parse(String(raw)) as Frame;
      if (frame.type === 'pong') {
        resolve();
        return;
      }
      if (frame.type === 'connected') {
        client.send(JSON.stringify(outbound));
        client.send(JSON.stringify({type: 'ping', timestamp: 1}));
        return;
      }
      frames.push(frame);
    });
  });
  client.terminate();
  return frames;
};

describe('conversation list history opt-in', () => {
  afterEach(async () => {
    await stopEngines();
  });

  it('answers UNSUPPORTED when history is disabled', async () => {
    const hal = createServer({
      app: (() => undefined) as unknown as Express,
      wsAuth: async () => ({id: 'u1'}),
      sessionStore: new InMemorySessionStore(),
      orchestrator: answeringOrchestrator,
      history: {enabled: false},
    });
    await hal.start(0);
    const {port} = hal.server.address() as AddressInfo;
    const url = `ws://127.0.0.1:${port}/hal/ws`;

    const frames = await askAfterConnect(url, {type: 'list_sessions'});

    expect(frames).toContainEqual(
      expect.objectContaining({
        type: 'error',
        code: 'UNSUPPORTED',
      })
    );
  });

  it('answers UNSUPPORTED when sessionStore does not support listing', async () => {
    const hal = createServer({
      app: (() => undefined) as unknown as Express,
      wsAuth: async () => ({id: 'u1'}),
      sessionStore: {
        create: (id: string) => Promise.resolve({sessionId: id, userId: 'u1', entries: []}),
        get: () => Promise.resolve(undefined),
        delete: () => Promise.resolve(true),
        count: () => Promise.resolve(0),
        clear: () => Promise.resolve(),
      } as any,
      orchestrator: answeringOrchestrator,
      history: {enabled: true},
    });
    await hal.start(0);
    const {port} = hal.server.address() as AddressInfo;
    const url = `ws://127.0.0.1:${port}/hal/ws`;

    const frames = await askAfterConnect(url, {type: 'list_sessions'});

    expect(frames).toContainEqual(
      expect.objectContaining({
        type: 'error',
        code: 'UNSUPPORTED',
      })
    );
  });
});

